Rules.InvariantScript:
Refresh(AI_KnowledgeBase);
Refresh(SystemManuals);
Refresh(Systems);
Refresh(KnowledgeGaps);
Set(varLastRefreshedTime, Now());
Notify("รีเฟรชข้อมูล SharePoint ทั้งหมดเรียบร้อยแล้ว", NotificationType.Success)

Patch(
    AI_KnowledgeBase,
    ThisItem,
    {
        Is_Active: If(Coalesce(ThisItem.Is_Active.Value, ThisItem.Is_Active, "Active") = "Active" || Coalesce(ThisItem.Is_Active.Value, ThisItem.Is_Active, "") = "Yes", { Value: "Inactive" }, { Value: "Active" })
    }
);
Notify("สลับสถานะ Q&A เรียบร้อยแล้ว", NotificationType.Success)

Set(varSelectedQnA, ThisItem);
Set(varConfirmAction, "DELETE_QNA");
Set(varConfirmMessage, "คุณแน่ใจหรือไม่ว่าต้องการลบคำถาม: '" & ThisItem.Issue_Title & "' ?");
Set(varShowConfirmModal, true)

If(
    IsBlank(txt_DrawerQuestion.Text) Or IsBlank(txt_DrawerAnswer.Text),
    Notify("กรุณากรอกคำถามและคำตอบที่อนุมัติให้ครบถ้วน", NotificationType.Error),
    If(
        varDrawerMode = "NEW_FROM_GAP",
        Patch(
            AI_KnowledgeBase,
            Defaults(AI_KnowledgeBase),
            {
                Title: "KB-" & Text(Now(), "yyyymmddhhmmss"),
                Issue_Title: txt_DrawerQuestion.Text,
                System: If(IsBlank(dd_DrawerSystem.Selected.Value), "General", dd_DrawerSystem.Selected.Value),
                Approved_Answer: txt_DrawerAnswer.Text,
                Required_Information: txt_DrawerReqInfo.Text,
                Review_Status: { Value: "Approved" },
                Is_Active: { Value: "Active" }
            }
        );
        Patch(
            KnowledgeGaps,
            varSelectedGap,
            {
                GapStatus: {Value: "Added to KB"}
            }
        );
        Set(varDrawerOpen, false);
        Notify("แปลงคำถามเข้าสู่ Q&A Knowledge Base สำเร็จแล้ว", NotificationType.Success),
        If(
            varDrawerMode = "NEW",
            Patch(
                AI_KnowledgeBase,
                Defaults(AI_KnowledgeBase),
                {
                    Title: "KB-" & Text(Now(), "yyyymmddhhmmss"),
                    Issue_Title: txt_DrawerQuestion.Text,
                    System: If(IsBlank(dd_DrawerSystem.Selected.Value), "General", dd_DrawerSystem.Selected.Value),
                    Approved_Answer: txt_DrawerAnswer.Text,
                    Required_Information: txt_DrawerReqInfo.Text,
                    Review_Status: { Value: "Approved" },
                    Is_Active: { Value: "Active" }
                }
            );
            Set(varDrawerOpen, false);
            Notify("บันทึกข้อมูล Q&A เรียบร้อยแล้ว", NotificationType.Success),
            Patch(
                AI_KnowledgeBase,
                varSelectedQnA,
                {
                    Issue_Title: txt_DrawerQuestion.Text,
                    System: If(IsBlank(dd_DrawerSystem.Selected.Value), varSelectedQnA.System, dd_DrawerSystem.Selected.Value),
                    Approved_Answer: txt_DrawerAnswer.Text,
                    Required_Information: txt_DrawerReqInfo.Text
                }
            );
            Set(varDrawerOpen, false);
            Notify("บันทึกการแก้ไข Q&A เรียบร้อยแล้ว", NotificationType.Success)
        )
    )
)

Remove(AI_KnowledgeBase, varSelectedQnA);
Set(varShowConfirmModal, false);
Notify("ลบข้อคำถาม Q&A เรียบร้อยแล้ว", NotificationType.Success)

Set(varUploadModalOpen, false);
Launch("https://dvsins.sharepoint.com/sites/PowerAppPRD/SystemManuals/" & If(IsBlank(dd_UploadSystem.Selected.Value), "", dd_UploadSystem.Selected.Value));
Notify("เปิด Document Library สำหรับวางไฟล์เรียบร้อยแล้ว", NotificationType.Information)
